export function createLeads() {
    let lead = '';
    let onSwap = () => { };
    let settled = false;
    const members = new Map();
    const oust = () => {
        let any = false;
        for (const [id, m] of members) {
            if (id === lead || !m.open())
                continue;
            any = true;
            m.oust();
        }
        return any;
    };
    return {
        claim: (id) => {
            lead = id;
            if (settled && oust())
                onSwap();
        },
        join: (id, member) => {
            members.set(id, member);
            return () => {
                members.delete(id);
                if (lead === id)
                    lead = '';
            };
        },
        settle: (swap) => {
            onSwap = swap;
            settled = true;
            if (lead)
                oust();
            return () => {
                settled = false;
            };
        },
    };
}
